import test from 'node:test';import assert from 'node:assert/strict';import {defaultDig,normalizeDig,digObjects,digFinds,digCell,digBlocked,digRoute,digSolid,digDuration,beginDig,tickDig,digVisible,digLessons,designView,normalizeDesigns,designFarmTarget} from '../src/excavation.js';import {objects,materials} from '../src/data.js';import {normalizeFarm,farmView,farmArtKey,farmArtKeys} from '../src/farm.js';import {getJournalEntries} from '../src/journal.js';
test('both side-view maps reach every station and find while avoiding the magma barrier',()=>{for(const level of [0,1])for(const o of digObjects.filter(o=>o.level===level)){const p=digRoute([100,180],[o.x,o.y],level);if(digCell(o.x,o.y).join()!=='2,4')assert.ok(p.length,o.id);for(const c of p)assert.equal(digBlocked(...c,level),false)}assert.deepEqual(digRoute([100,180],[740,500],1),[])});
test('one destination input automatically clears terrain; interruption replaces the old target',()=>{const s=defaultDig();let pos=[100,180];assert.equal(digVisible(s,digObjects.find(o=>o.find==='quartz')),false);beginDig(s,pos,[300,260],'dig-quartz');let arrived=null;const found=new Set();for(let i=0;i<600;i++){const r=tickDig(s,pos,.05,0);pos=r.position;if(r.found)found.add(r.found);if(r.arrived){arrived=r.arrived;break}}assert.equal(arrived,'dig-quartz');assert.ok(found.has('quartz'));assert.equal(digSolid(s,...digCell(...pos)),false);const old=s.cleared[0].length;beginDig(s,pos,[860,420],'old');beginDig(s,pos,[100,180],'dig-exit');assert.equal(s.target,'dig-exit');assert.equal(s.cleared[0].length,old);assert.deepEqual(normalizeDig(s).cleared,s.cleared);assert.equal(normalizeDig(s).path.length,0)});
test('Aiden is faster with hard rock; PIP-assisted other crew can still complete it',()=>{for(const tool of ['drill','scoop','arms']){const s={...defaultDig(),tool};assert.ok(digDuration(s,18,8,3)<digDuration(s,18,8,0));beginDig(s,[100,180],[740,340],'dig-iron');let pos=[100,180],done=false;for(let i=0;i<1500;i++){const r=tickDig(s,pos,.05,0);pos=r.position;if(r.arrived){done=true;break}}assert.ok(done)}});
test('new finds are journaled; fossils remain observations rather than construction inputs',()=>{const found=new Set(digFinds.map(f=>f.id));const journal=getJournalEntries('found',found,new Set(),objects,materials);for(const f of digFinds)assert.ok(journal.some(e=>e.id===f.id&&objects.some(o=>o.id===e.target)));const minerals=getJournalEntries('minerals',found,new Set(),objects,materials);assert.ok(!minerals.some(e=>['fossil','granite','basalt'].includes(e.id)));assert.ok(!designView('bridge',found).samples.some(f=>f.id==='fossil'));assert.deepEqual(normalizeDesigns({bridge:'granite',water:'fossil',fake:'iron'}),{bridge:'granite'})});
test('engineering deployments remain validated, reusable and available to farm models',()=>{for(const project of ['bridge','water','habitat']){const f=normalizeFarm({upgrades:{[project]:'quartz'}});assert.equal(f.upgrades[project],'quartz');assert.ok(objects.some(o=>o.id===designFarmTarget(project)));const route=project==='bridge'?'vertical':project==='water'?'recycle':'biodome';assert.ok(farmArtKeys.includes(farmArtKey(f,route)));assert.equal(f.upgrades[project],'quartz')}assert.equal(normalizeFarm({upgrades:{habitat:'fossil'}}).upgrades.habitat,undefined);assert.match(farmView(normalizeFarm({upgrades:{habitat:'quartz'}}),'biodome').body,/module is installed/)});
test('cave science distinguishes mantle/magma, pigment/albinism and groundwater pores',()=>{assert.match(digLessons.mantle.text,/mostly solid/);assert.match(digLessons.groundwater.text,/pores and cracks/);assert.match(digLessons.pigment.text,/not all albino/);assert.match(digLessons.echo.text,/not all blind/)});
